const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const point = ee.Geometry.Point([-1.187011, 29.135547]);
  const aoi = point.buffer(5000); // 5km buffer around the point

  const date1 = '2024-08-12';
  const date2 = '2024-09-29';

  // 2. Data Acquisition & Check
  const s2_col1 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(aoi)
    .filterDate(date1, ee.Date(date1).advance(1, 'day'))
    .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 50));

  const s2_col2 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(aoi)
    .filterDate(date2, ee.Date(date2).advance(1, 'day'))
    .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 50));

  const size1 = await s2_col1.size().getInfo();
  const size2 = await s2_col2.size().getInfo();

  console.log(`Images on ${date1}: ${size1}`);
  console.log(`Images on ${date2}: ${size2}`);

  if (size1 === 0 || size2 === 0) {
    console.log("Missing data for one or both dates.");
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Calculate MNDWI and water extent
  function addMNDWI(image) {
    const mndwi = image.normalizedDifference(['B3', 'B11']).rename('MNDWI');
    return image.addBands(mndwi);
  }

  function maskClouds(image) {
    const scl = image.select('SCL');
    const mask = scl.neq(3).and(scl.neq(8)).and(scl.neq(9)).and(scl.neq(10));
    return image.updateMask(mask);
  }

  const img1 = s2_col1.map(maskClouds).map(addMNDWI).median();
  const img2 = s2_col2.map(maskClouds).map(addMNDWI).median();

  // Water threshold: MNDWI > 0
  const water1 = img1.select('MNDWI').gt(0);
  const water2 = img2.select('MNDWI').gt(0);

  // 4. Calculation - Count water pixels
  const count1Stats = await water1.reduceRegion({
    reducer: ee.Reducer.sum().combine(ee.Reducer.count(), '', true),
    geometry: aoi,
    scale: 3000,
    maxPixels: 1e9
  }).getInfo();

  const count2Stats = await water2.reduceRegion({
    reducer: ee.Reducer.sum().combine(ee.Reducer.count(), '', true),
    geometry: aoi,
    scale: 3000,
    maxPixels: 1e9
  }).getInfo();

  const waterPixels1 = count1Stats['MNDWI_sum'];
  const validPixels1 = count1Stats['MNDWI_count'];
  const waterPixels2 = count2Stats['MNDWI_sum'];
  const validPixels2 = count2Stats['MNDWI_count'];

  console.log(`${date1}: Valid pixels=${validPixels1}, Water pixels=${waterPixels1}`);
  console.log(`${date2}: Valid pixels=${validPixels2}, Water pixels=${waterPixels2}`);

  // 5. Validation & Final Answer
  if (validPixels1 === 0 || validPixels2 === 0) {
    console.log("No valid pixels after cloud masking.");
    console.log("<answer>C2</answer>");
    return;
  }

  if (waterPixels1 === null || waterPixels2 === null || 
      waterPixels1 === undefined || waterPixels2 === undefined) {
    console.log("Calculation failed.");
    console.log("<answer>C3</answer>");
    return;
  }

  const diff = waterPixels2 - waterPixels1;
  console.log(`Water extent change: ${diff > 0 ? '+' : ''}${diff.toFixed(0)} pixels`);

  if (diff > 0) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
